UPDATE icono_manifestation_revisions AS r
   SET body_sha256 = fix.new_sha256, body_bytes = fix.new_bytes
  FROM fix
 WHERE r.manifestation_revision_id = fix.revision_id AND r.body_sha256 = fix.old_sha256
